#!/usr/bin/env python3
import json
import sys
from datetime import datetime

def extract_session(path):
    """Extract readable content and metadata from Claude Code session file."""
    messages = []
    for line in open(path, errors='replace'):
        line = line.strip()
        if not line:
            continue
        try:
            j = json.loads(line)
            ts = j.get('timestamp', '')[:16]
            typ = j.get('type')

            if typ in ('user', 'assistant'):
                msg = j.get('message', {})
                if isinstance(msg, dict):
                    content = msg.get('content', '')
                else:
                    content = str(msg)
                if isinstance(content, list):
                    texts = []
                    for c in content:
                        if isinstance(c, dict):
                            if c.get('type') == 'text':
                                texts.append(c.get('text', ''))
                        else:
                            texts.append(str(c))
                    content = ' '.join(texts)
                content = (' '.join(str(content).split()))
                messages.append({'ts': ts, 'role': typ, 'text': content[:1000]})
        except Exception:
            pass
    return messages

if __name__ == '__main__':
    path = sys.argv[1]
    msgs = extract_session(path)
    for m in msgs:
        print(f"{m['ts']} {m['role']}: {m['text'][:300]}")
