                        texts = [c.get('text','') if isinstance(c,dict) else str(c) for c in text]
                        text = ' '.join(texts)

                    # Try to parse JSON judgments
                    if text.strip().startswith('{'):
                        try:
                            judgment = json.loads(text)
                            offences = judgment.get('offences', [])
